  "A documented plan with realistic projections": "யதார்த்தமான கணிப்புகளுடன் ஆவணப்படுத்தப்பட்ட திட்டம்",
  "A fall in gold prices can trigger a margin call requiring you to pay down or pledge more": "தங்க விலை சரிந்தால் மார்ஜின் கால் வரலாம், அப்போது நீங்கள் தொகை செலுத்தவோ மேலும் அடகு வைக்கவோ வேண்டும்",
