  "Bandhan Bank": "பந்தன் வங்கி",
  "Bands are indicative of general market practice. Every lender applies its own policy, and no score guarantees an outcome.": "வரம்புகள் பொதுவான சந்தை நடைமுறையைச் சுட்டுகின்றன. ஒவ்வொரு கடன் வழங்குநரும் தன் கொள்கையைப் பயன்படுத்துகிறார், எந்த மதிப்பெண்ணும் முடிவுக்கு உத்தரவாதம் அல்ல.",
  "Bank": "வங்கி",
  "Bank & NBFC partners": "வங்கி & NBFC பங்குதாரர்கள்",
