  "Bank statements available digitally or via account aggregator": "டிஜிட்டல் முறையில் அல்லது கணக்குத் திரட்டி வழியாகக் கிடைக்கும் வங்கி அறிக்கைகள்",
  "Bank statements showing salary credits": "சம்பள வரவைக் காட்டும் வங்கி அறிக்கைகள்",
  "Bank-level data security": "வங்கி அளவிலான தரவுப் பாதுகாப்பு",
  "Bank-wise Offers": "வங்கி வாரியான சலுகைகள்",
  "Banks": "வங்கிகள்",
