  "Brokerage, statutory charges, demat annual maintenance and transaction fees all apply.": "தரகு, சட்டப்பூர்வக் கட்டணங்கள், டீமேட் ஆண்டுப் பராமரிப்பு மற்றும் பரிவர்த்தனைக் கட்டணங்கள் அனைத்தும் பொருந்தும்.",
  "Browse loan and financial products, and read what each one actually involves.": "கடன் மற்றும் நிதித் தயாரிப்புகளைப் பாருங்கள், ஒவ்வொன்றிலும் உண்மையில் என்ன அடங்கும் எனப் படியுங்கள்.",
  "Browse loan products": "கடன் தயாரிப்புகளைப் பார்",
