  "Credit life cover and other add-ons are optional on the products we list. Check whether one has been included in your quote.": "நாங்கள் பட்டியலிடும் தயாரிப்புகளில் கடன் ஆயுள் காப்பீடும் பிற கூடுதல் அம்சங்களும் விருப்பத்தேர்வு. உங்கள் விலைப்பட்டியலில் ஏதேனும் சேர்க்கப்பட்டுள்ளதா எனச் சரிபார்க்கவும்.",
