  "Decide what you need and over how long, then compare every offer on those same terms.": "உங்களுக்கு என்ன, எவ்வளவு காலத்திற்குத் தேவை என முடிவு செய்யுங்கள், பின் ஒவ்வொரு சலுகையையும் அதே நிபந்தனைகளில் ஒப்பிடுங்கள்.",
  "Decide whether to keep the EMI and shorten the tenure, or lower the EMI. Shortening saves far more interest.": "EMI-ஐ அப்படியே வைத்துக் காலத்தைக் குறைப்பதா, அல்லது EMI-ஐக் குறைப்பதா என முடிவு செய்யுங்கள். காலத்தைக் குறைப்பது மிக அதிக வட்டியைச் சேமிக்கும்.",
  "Decision and disbursal much faster than a branch process": "கிளை செயல்முறையை விட முடிவும் வழங்கலும் மிக விரைவு",
