  "Digitally fetched or uploaded bank statements": "டிஜிட்டல் முறையில் பெறப்பட்ட அல்லது பதிவேற்றப்பட்ட வங்கி அறிக்கைகள்",
  "Direct-plan mutual funds with no commission built into the NAV, plus goal-based SIP planning reviewed twice a year.": "NAV-இல் கமிஷன் இல்லாத நேரடித் திட்ட பரஸ்பர நிதிகள், மற்றும் ஆண்டுக்கு இருமுறை மறுபரிசீலனை செய்யப்படும் இலக்கு அடிப்படையிலான SIP திட்டமிடல்.",
