  "Diversify — a concentrated portfolio can fall a very long way.": "பன்முகப்படுத்துங்கள் — செறிவான போர்ட்ஃபோலியோ மிகவும் வீழலாம்.",
  "DLF Cyber City, Building 8, Tower C, Sector 24, Gurugram 122002": "DLF சைபர் சிட்டி, கட்டிடம் 8, டவர் C, செக்டார் 24, குருகிராம் 122002",
  "Do home loan tax benefits apply to a plot loan?": "வீட்டுக் கடன் வரிச் சலுகைகள் மனைக் கடனுக்குப் பொருந்துமா?",
  "Do I have to submit documents more than once?": "ஆவணங்களை ஒன்றுக்கு மேற்பட்ட முறை சமர்ப்பிக்க வேண்டுமா?",
  "Do I need collateral?": "எனக்குப் பிணையம் தேவையா?",
  "Do I need existing fleet experience?": "எனக்கு ஏற்கனவே வாகனத் தொகுப்பு அனுபவம் தேவையா?",
  "Do I own the equipment during the loan?": "கடன் காலத்தில் உபகரணம் என் உரிமையில் இருக்குமா?",
  "Do I still receive dividends?": "நான் இன்னும் ஈவுத்தொகை பெறுவேனா?",
  "Do stones in my jewellery count towards the loan?": "எனது நகைகளில் உள்ள கற்கள் கடனுக்குக் கணக்கிடப்படுமா?",
  "Doctor, Chennai": "மருத்துவர், சென்னை",
  "Document Support": "ஆவண ஆதரவு",
  "Document Verification": "ஆவணச் சரிபார்ப்பு",
  "Document verification required": "ஆவணச் சரிபார்ப்பு தேவை",
  "Documentation": "ஆவணப்படுத்தல்",
  "Documentation / stamping": "ஆவணப்படுத்தல் / முத்திரையிடல்",
  "Documentation and attestation": "ஆவணப்படுத்தல் மற்றும் சான்றளித்தல்",
  "Documentation you should expect": "நீங்கள் எதிர்பார்க்க வேண்டிய ஆவணங்கள்",
  "Documentation, stamping, valuation and late-payment charges vary by lender and product.": "ஆவணப்படுத்தல், முத்திரைக் கட்டணம், மதிப்பீடு மற்றும் தாமதக் கட்டணங்கள் கடன் வழங்குநர் மற்றும் தயாரிப்பைப் பொறுத்து மாறுபடும்.",
  "Documented business income": "ஆவணப்படுத்தப்பட்ட வணிக வருமானம்",
  "Documented business or contract income": "ஆவணப்படுத்தப்பட்ட வணிக அல்லது ஒப்பந்த வருமானம்",
  "Documented business or rental income": "ஆவணப்படுத்தப்பட்ட வணிக அல்லது வாடகை வருமானம்",
  "Documented income": "ஆவணப்படுத்தப்பட்ட வருமானம்",
  "Documented income sufficient to service the EMI": "EMI செலுத்தப் போதுமான ஆவணப்படுத்தப்பட்ட வருமானம்",
  "Documented income to service the EMI": "EMI செலுத்த ஆவணப்படுத்தப்பட்ட வருமானம்",
  "Documented income, salaried or self-employed": "ஆவணப்படுத்தப்பட்ட வருமானம், சம்பளதாரர் அல்லது சுயதொழில்",
  "Documented, regular income": "ஆவணப்படுத்தப்பட்ட, வழக்கமான வருமானம்",
  "Documents": "ஆவணங்கள்",
  "Documents and the application process": "ஆவணங்கள் மற்றும் விண்ணப்ப செயல்முறை",
  "Documents are shared only with lenders you choose to apply to.": "ஆவணங்கள் நீங்கள் விண்ணப்பிக்கத் தேர்ந்தெடுக்கும் கடன் வழங்குநர்களுடன் மட்டுமே பகிரப்படும்.",
  "Documents that do not match the letter of credit exactly are rejected — precision matters more than intent.": "கடன் கடிதத்துடன் அச்சொட்டாகப் பொருந்தாத ஆவணங்கள் நிராகரிக்கப்படும் — நோக்கத்தை விடத் துல்லியமே முக்கியம்.",
  "Documents Verified": "ஆவணங்கள் சரிபார்க்கப்பட்டன",
  "Documents you upload are shared only with lenders you choose to apply to.": "நீங்கள் பதிவேற்றும் ஆவணங்கள் நீங்கள் விண்ணப்பிக்கத் தேர்ந்தெடுக்கும் கடன் வழங்குநர்களுடன் மட்டுமே பகிரப்படும்.",
  "Documents you will need": "தேவையான ஆவணங்கள்",
  "Does a credit guarantee mean I cannot default?": "கடன் உத்தரவாதம் என்றால் நான் தவற முடியாது என்பதா?",
  "Does a lower rate always mean a cheaper loan?": "குறைந்த விகிதம் எப்போதும் மலிவான கடனா?",
  "Does checking eligibility affect my credit score?": "தகுதியைச் சரிபார்ப்பது எனது கடன் மதிப்பெண்ணைப் பாதிக்குமா?",
  "Does checking my eligibility affect my credit score?": "தகுதியைச் சரிபார்ப்பது எனது கடன் மதிப்பெண்ணைப் பாதிக்குமா?",
  "Does checking my own score lower it?": "எனது சொந்த மதிப்பெண்ணைப் பார்த்தால் அது குறையுமா?",
  "Does not affect your own applications, offers or credit record.": "உங்கள் சொந்த விண்ணப்பங்கள், சலுகைகள் அல்லது கடன் பதிவைப் பாதிக்காது.",
  "Does not share any of your personal or financial information with them.": "அவர்களுடன் உங்கள் தனிப்பட்ட அல்லது நிதித் தகவல் எதையும் பகிர்வதில்லை.",
  "Does this platform give investment advice?": "இந்தத் தளம் முதலீட்டு ஆலோசனை வழங்குகிறதா?",
  "Down payment requirement is modest": "முன்பணத் தேவை குறைவு",
  "Down payment, registration and insurance are payable upfront": "முன்பணம், பதிவு மற்றும் காப்பீடு முன்கூட்டியே செலுத்த வேண்டியவை",
  "Download": "பதிவிறக்கு",
