  "Earn miles or points, sometimes with lounge access. Worth the fee only if you genuinely use the benefits.": "மைல்கள் அல்லது புள்ளிகளைப் பெறுங்கள், சில நேரங்களில் ஓய்வறை அணுகலுடன். சலுகைகளை உண்மையில் பயன்படுத்தினால் மட்டுமே கட்டணம் மதிப்புள்ளது.",
