  "Eligibility results are indicative and do not guarantee loan approval. Your lender decides the final outcome.": "தகுதி முடிவுகள் சுட்டிக்காட்டுபவை மட்டுமே, கடன் ஒப்புதலுக்கு உத்தரவாதம் அல்ல. இறுதி முடிவை உங்கள் கடன் வழங்குநர் எடுக்கிறார்.",
