  "Flexible Use": "நெகிழ்வான பயன்பாடு",
  "Floating": "மாறுபடும்",
  "Floating loans reset on a schedule set in your agreement. Knowing yours tells you when a change will reach your EMI.": "மிதவைக் கடன்கள் உங்கள் ஒப்பந்தத்தில் நிர்ணயித்த அட்டவணைப்படி மறுஅமைவு பெறும். உங்களுடையதை அறிந்தால் மாற்றம் எப்போது உங்கள் EMI-ஐ எட்டும் எனத் தெரியும்.",
  "Floating rate": "மாறும் வட்டி விகிதம்",
