  "For banks, NBFCs, insurers and distribution partners.": "வங்கிகள், NBFC-கள், காப்பீட்டாளர்கள் மற்றும் விநியோகப் பங்குதாரர்களுக்கு.",
  "For creating and releasing the pledge.": "அடகு உருவாக்க மற்றும் விடுவிக்க.",
  "For growing your business": "உங்கள் வணிகத்தை வளர்க்க",
  "For inspecting and valuing the vehicle.": "வாகனத்தை ஆய்வு செய்து மதிப்பிடுவதற்கு.",
  "For owners holding a valid long-term third-party policy who want to add own-damage cover separately.": "செல்லுபடியாகும் நீண்டகால மூன்றாம் தரப்பு பாலிசி வைத்திருந்து, சொந்தச் சேதக் காப்பீட்டைத் தனியாகச் சேர்க்க விரும்பும் உரிமையாளர்களுக்கு.",
  "For variable bills, consider a cap on the mandate where your bank supports one.": "மாறும் பில்களுக்கு, உங்கள் வங்கி அனுமதித்தால் ஆணையில் உச்சவரம்பு வைப்பதைப் பரிசீலியுங்கள்.",
