  "Foreign exchange transactions are governed by FEMA and executed by authorised dealers. Rates move continuously.": "அன்னியச் செலாவணி பரிவர்த்தனைகள் FEMA-வால் ஆளப்படுகின்றன, அங்கீகரிக்கப்பட்ட வணிகர்களால் நிறைவேற்றப்படுகின்றன. விகிதங்கள் தொடர்ந்து மாறும்.",
