  "From {rate} p.a.": "{rate} ஆண்டுக்கு முதல்",
  "Full KYC, income verification, a credit check and the lender’s final credit decision.": "முழு KYC, வருமானச் சரிபார்ப்பு, கடன் தகுதிப் பரிசோதனை மற்றும் கடன் வழங்குநரின் இறுதி முடிவு.",
  "Full name": "முழு பெயர்",
  "Fully online, no branch visit": "முழுவதும் ஆன்லைன், கிளைக்குச் செல்ல வேண்டாம்",
  "Funding a business that trades, buys or sells across borders.": "எல்லைகளைத் தாண்டி வர்த்தகம், வாங்குதல் அல்லது விற்பனை செய்யும் வணிகத்திற்கு நிதி.",
  "Funding study abroad, where the loan is only part of the planning.": "வெளிநாட்டுப் படிப்புக்கு நிதி, அங்கு கடன் திட்டமிடலின் ஒரு பகுதி மட்டுமே.",
  "Funds for treatment costs that insurance does not cover.": "காப்பீடு ஈடுசெய்யாத சிகிச்சைச் செலவுகளுக்கான நிதி.",
  "Funds growth without diluting ownership": "உரிமையைக் குறைக்காமல் வளர்ச்சிக்கு நிதி",
  "Funds move between this account and your trading account.": "நிதி இந்தக் கணக்குக்கும் உங்கள் வர்த்தகக் கணக்குக்கும் இடையே நகரும்.",
  "Funds the day-to-day operating cycle, not long-term assets.": "நாளாந்த செயல்பாட்டுச் சுழற்சிக்கு நிதியளிக்கிறது, நீண்டகாலச் சொத்துகளுக்கு அல்ல.",
  "Gain": "ஆதாயம்",
  "Gainers and losers": "உயர்ந்தவை மற்றும் வீழ்ந்தவை",
  "Gather your evidence": "உங்கள் ஆதாரங்களைச் சேகரியுங்கள்",
  "General enquiries and advisory contact.": "பொது விசாரணைகள் மற்றும் ஆலோசனைத் தொடர்பு.",
  "Generally acceptable to most lenders": "பொதுவாக பெரும்பாலான கடன் வழங்குநர்களுக்கு ஏற்புடையது",
  "Generally lower than a secured facility": "பொதுவாக பிணைய வசதியை விடக் குறைவு",
  "Generally nil across lenders.": "பொதுவாக அனைத்து கடன் வழங்குநர்களிடமும் இல்லை.",
  "Generally not applicable.": "பொதுவாகப் பொருந்தாது.",
  "Generally yes — you remain the owner. Confirm the specific terms with your lender.": "பொதுவாக ஆம் — உரிமை உங்களிடமே இருக்கும். குறிப்பிட்ட விதிமுறைகளை உங்கள் கடன் வழங்குநரிடம் உறுதிப்படுத்துங்கள்.",
