  "Longer tenures available than unsecured business credit": "பிணையமற்ற வணிகக் கடனை விட நீண்ட காலங்கள் கிடைக்கும்",
  "Longer tenures keep instalments manageable": "நீண்ட காலம் தவணைகளை சமாளிக்கக்கூடியதாக வைக்கிறது",
  "Look for days-past-due markers you do not recognise.": "நீங்கள் அறியாத தாமத-நாள் குறிப்புகளைத் தேடுங்கள்.",
