  "Lower rates than unsecured borrowing": "பிணையமற்ற கடனை விடக் குறைந்த விகிதங்கள்",
  "Lowest LTV of the LAP family — expect a conservative valuation": "LAP வகையில் மிகக் குறைந்த LTV — கவனமான மதிப்பீட்டை எதிர்பாருங்கள்",
  "Lowest Rate Finder": "குறைந்த விகித தேடல்",
  "Lowest rates available to individual borrowers": "தனிநபர் கடன் பெறுநர்களுக்குக் கிடைக்கும் மிகக் குறைந்த விகிதங்கள்",
  "LTV — Loan to Value": "LTV — கடன் மதிப்பு விகிதம்",
