  "Manufacturers and service businesses within MSME thresholds": "MSME வரம்புகளுக்குள் உற்பத்தியாளர்கள் மற்றும் சேவை வணிகங்கள்",
  "Many lenders decline agricultural land outright": "பல கடன் வழங்குநர்கள் விவசாய நிலத்தை நேரடியாக நிராகரிக்கின்றனர்",
  "Many lenders disburse within the same visit once valuation and KYC are complete. No lender guarantees a specific time.": "மதிப்பீடும் KYC-யும் முடிந்ததும் பல கடன் வழங்குநர்கள் அதே வருகையிலேயே வழங்குகிறார்கள். எந்தக் கடன் வழங்குநரும் குறிப்பிட்ட நேரத்திற்கு உத்தரவாதம் தருவதில்லை.",
  "Many lenders maintain lists of recognised institutions, with better terms for those on them.": "பல கடன் வழங்குநர்கள் அங்கீகரிக்கப்பட்ட நிறுவனங்களின் பட்டியலை வைத்திருக்கிறார்கள், அவற்றில் உள்ளவர்களுக்கு நிபந்தனைகள் சிறந்தவை.",
  "Map placeholder": "வரைபட இடம்",
  "Margin contribution from own funds, as set by the lender": "கடன் வழங்குநர் நிர்ணயிக்கும் சொந்த நிதியிலிருந்து மார்ஜின் பங்களிப்பு",
  "Margin trading facility": "மார்ஜின் வர்த்தக வசதி",
