  "Market returns are not guaranteed and vary year to year. This is an assumption you set, not a projection.": "சந்தை வருவாய் உத்தரவாதமற்றது, ஆண்டுதோறும் மாறும். இது நீங்கள் அமைத்த ஓர் அனுமானம், முன்கணிப்பு அல்ல.",
