  "Often a small flat amount, set by the lender.": "பெரும்பாலும் ஒரு சிறிய நிலையான தொகை, கடன் வழங்குநர் நிர்ணயிப்பது.",
  "Often nil after a short initial period.": "குறுகிய ஆரம்பக் காலத்திற்குப் பின் பெரும்பாலும் இல்லை.",
  "Often nil or low for domestic courses; overseas loans may attract a charge.": "உள்நாட்டுப் படிப்புகளுக்கு பெரும்பாலும் இல்லை அல்லது குறைவு; வெளிநாட்டுக் கடன்களுக்குக் கட்டணம் இருக்கலாம்.",
  "Often nil or nominal.": "பெரும்பாலும் இல்லை அல்லது பெயரளவு.",
  "Often, yes — particularly if you hold a competing written offer, or have an existing relationship with the lender.": "பெரும்பாலும், ஆம் — குறிப்பாக உங்களிடம் போட்டியிடும் எழுத்துபூர்வ சலுகை இருந்தால், அல்லது கடன் வழங்குநருடன் ஏற்கனவே தொடர்பு இருந்தால்.",
