  "On-road price includes registration and insurance, which the loan may not fully cover": "ஆன்-ரோடு விலையில் பதிவு மற்றும் காப்பீடு அடங்கும், அவற்றைக் கடன் முழுமையாக ஈடுசெய்யாமல் போகலாம்",
