  "One International Center, Tower 3, Senapati Bapat Marg, Mumbai 400013": "ஒன் இன்டர்நேஷனல் சென்டர், டவர் 3, சேனாபதி பாபட் மார்க், மும்பை 400013",
  "One upload, shared securely with your chosen lender. We chase the follow-up queries so you do not have to.": "ஒரே பதிவேற்றம், உங்கள் தேர்வுசெய்த கடன் வழங்குநருடன் பாதுகாப்பாகப் பகிரப்படும். தொடர் கேள்விகளை நாங்கள் கவனிக்கிறோம், நீங்கள் அல்ல.",
