  "Only the net gold content counts — stones and settings are excluded from valuation": "நிகர தங்க அளவு மட்டுமே கணக்கிடப்படும் — கற்கள் மற்றும் பதிப்புகள் மதிப்பீட்டில் இல்லை",
  "Open menu": "மெனுவைத் திற",
