  "Our team files and follows your claim with the insurer, including the document back-and-forth nobody warns you about.": "எங்கள் குழு காப்பீட்டாளரிடம் உங்கள் உரிமைகோரலைத் தாக்கல் செய்து பின்தொடர்கிறது, யாரும் முன்கூட்டி எச்சரிக்காத ஆவணப் போக்குவரத்து உட்பட.",
  "Our team replies within one working day. We’ll email updates to your registered address.": "எங்கள் குழு ஒரு வேலை நாளுக்குள் பதிலளிக்கும். புதுப்பிப்புகளை உங்கள் பதிவு செய்த முகவரிக்கு மின்னஞ்சல் செய்வோம்.",
