  "Report a fraudulent transaction to your bank immediately, and to the national cybercrime helpline.": "மோசடிப் பரிவர்த்தனையை உடனடியாக உங்கள் வங்கிக்கும் தேசிய இணையக் குற்ற உதவி எண்ணுக்கும் தெரிவியுங்கள்.",
