  "Review prepayment and foreclosure terms in case your circumstances change.": "சூழ்நிலைகள் மாறினால் முன்கூட்டிய செலுத்தல் மற்றும் அடைப்பு விதிமுறைகளை மதிப்பாய்வு செய்யுங்கள்.",
