  "Sale agreement with the seller": "விற்பனையாளருடன் விற்பனை ஒப்பந்தம்",
  "Sale agreement, title deed and approved building plan": "விற்பனை ஒப்பந்தம், பத்திரம் மற்றும் அங்கீகரிக்கப்பட்ட கட்டட வரைபடம்",
  "Same favourable rate treatment as other home loans": "பிற வீட்டுக் கடன்களைப் போன்ற சாதகமான விகிதம்",
  "Same structure as car insurance, with its own premium and IDV calculation.": "கார் காப்பீட்டைப் போன்ற அமைப்பு, அதன் சொந்த பிரீமியம் மற்றும் IDV கணக்கீட்டுடன்.",
  "Same sum assured, same rider set, side-by-side premiums from every partner insurer we work with.": "ஒரே காப்பீட்டுத் தொகை, ஒரே கூடுதல் அம்சத் தொகுப்பு, எங்கள் ஒவ்வொரு கூட்டாளி காப்பீட்டாளரின் பிரீமியமும் அருகருகே.",
  "Same-day funds against pledged jewellery.": "அடகு நகைகளுக்கு அதே நாளில் நிதி.",
  "Sample content": "மாதிரி உள்ளடக்கம்",
