  "Saved": "சேமிப்பு",
  "Savers who would otherwise break a deposit and lose interest": "இல்லையெனில் வைப்பை உடைத்து வட்டியை இழக்கும் சேமிப்பாளர்கள்",
  "Saving in advance for the same trip costs nothing in interest": "அதே பயணத்திற்கு முன்கூட்டியே சேமிப்பதற்கு வட்டி எதுவும் இல்லை",
  "Savings and ULIP": "சேமிப்பு மற்றும் ULIP",
