  "SBI Bank": "SBI வங்கி",
  "Scheme eligibility and terms change — confirm what currently applies": "திட்டத் தகுதியும் விதிமுறைகளும் மாறும் — தற்போது எது பொருந்தும் என உறுதிப்படுத்துங்கள்",
  "Score factors": "மதிப்பெண் காரணிகள்",
  "Score, income stability and existing obligations determine where within a lender’s band you are priced.": "மதிப்பெண், வருமான நிலைத்தன்மை மற்றும் தற்போதைய கடமைகள், கடன் வழங்குநரின் விகித வரம்பில் உங்கள் இடத்தைத் தீர்மானிக்கின்றன.",
  "Screenshots of QR codes sent by strangers are a common fraud vector. Scan only codes you trust.": "அந்நியர்கள் அனுப்பும் QR குறியீட்டுத் திரைப்படங்கள் மோசடியின் பொதுவான வழி. நம்பகமான குறியீடுகளை மட்டும் ஸ்கேன் செய்யுங்கள்.",
  "Search for loans, banks, offers, calculators...": "கடன்கள், வங்கிகள், சலுகைகள், கால்குலேட்டர்களைத் தேடு...",
  "Search for the word you are stuck on.": "நீங்கள் தடுமாறும் சொல்லைத் தேடுங்கள்.",
