  "Secured": "பிணையுடன்",
  "Secured against gold jewellery, usually the fastest to disburse.": "தங்க நகைகள் மீது பிணையம், பொதுவாக மிக விரைவான வழங்கல்.",
  "Secured against pledged gold, settled fastest.": "அடகு தங்கத்தால் பாதுகாக்கப்பட்டது, மிக விரைவான தீர்வு.",
  "Secured against the vehicle, so rates are lower than unsecured borrowing": "வாகனத்தின் மீது பிணையம், எனவே விகிதங்கள் பிணையமற்ற கடனை விடக் குறைவு",
