  "Secures land now for construction later": "பின்னர் கட்டுமானத்திற்கு இப்போதே நிலத்தைப் பெறுகிறது",
  "Securing land ahead of construction": "கட்டுமானத்திற்கு முன் நிலத்தைப் பெறுதல்",
  "Security": "பாதுகாப்பு",
  "Security and support": "பாதுகாப்பு மற்றும் ஆதரவு",
  "See interest rates, EMI, tenure, processing fees and total repayment side by side before you commit.": "உறுதியளிக்கும் முன் வட்டி விகிதங்கள், EMI, காலம், செயலாக்கக் கட்டணங்கள் மற்றும் மொத்தத் திருப்பிச் செலுத்தலை அருகருகே பாருங்கள்.",
  "See lenders side by side on rate, fee, tenure and total cost — not just the headline number.": "விகிதம், கட்டணம், காலம் மற்றும் மொத்தச் செலவில் கடன் வழங்குநர்களை அருகருகே பாருங்கள் — தலைப்பு எண்ணில் மட்டும் அல்ல.",
  "See real rates from 50+ lenders, ranked by what you actually qualify for.": "50+ கடன் வழங்குநர்களின் உண்மையான விகிதங்களைப் பாருங்கள், நீங்கள் உண்மையில் தகுதி பெறுவதன்படி வரிசைப்படுத்தப்பட்டவை.",
  "See what you may qualify for.": "நீங்கள் எதற்குத் தகுதியுடையவர் என்பதைப் பாருங்கள்.",
  "Select a loan type": "கடன் வகையைத் தேர்ந்தெடு",
  "Self-employed professionals with filed returns": "வருமான வரி தாக்கல் செய்த சுயதொழில் நிபுணர்கள்",
  "Self-employed, Pune": "சுயதொழில், புனே",
  "Send enquiry": "விசாரணையை அனுப்பு",
  "Send message": "செய்தியை அனுப்பு",
  "Send us an enquiry": "எங்களுக்கு விசாரணை அனுப்பு",
  "Sentimental jewellery is at genuine risk — borrow only what you can repay": "உணர்வுபூர்வ நகைகள் உண்மையான ஆபத்தில் — திருப்பிச் செலுத்தக்கூடிய அளவே கடன் வாங்குங்கள்",
  "September 2026": "செப்டம்பர் 2026",
  "Service": "சேவை",
  "Service businesses buying specialised equipment": "சிறப்பு உபகரணங்கள் வாங்கும் சேவை வணிகங்கள்",
  "Service businesses with few physical assets": "குறைந்த இயற்பியல் சொத்துகளுள்ள சேவை வணிகங்கள்",
  "Service levels for decisions and disbursal.": "முடிவுகள் மற்றும் வழங்கலுக்கான சேவை நிலைகள்.",
