  "Short-term working capital": "குறுகிய கால நடைமுறை மூலதனம்",
  "Shorter tenures mean less total interest": "குறுகிய காலம் என்பது குறைந்த மொத்த வட்டி",
  "Should I borrow or claim on insurance?": "நான் கடன் வாங்க வேண்டுமா அல்லது காப்பீடு கோர வேண்டுமா?",
  "Should I choose a longer or shorter tenure?": "நீண்ட அல்லது குறுகிய காலத்தைத் தேர்ந்தெடுக்க வேண்டுமா?",
  "Should I choose a shorter tenure?": "நான் குறுகிய காலத்தைத் தேர்ந்தெடுக்க வேண்டுமா?",
  "Should I take dealer finance or arrange my own?": "விற்பனையாளர் நிதி பெறவா அல்லது நானே ஏற்பாடு செய்யவா?",
