  "Updated income proof and bank statements": "புதுப்பிக்கப்பட்ட வருமானச் சான்று மற்றும் வங்கி அறிக்கைகள்",
  "Upgrading the family car": "குடும்பக் காரை மேம்படுத்துதல்",
