  "You fund a margin from your own resources": "நீங்கள் உங்கள் சொந்த வளங்களிலிருந்து மார்ஜின் அளிக்கிறீர்கள்",
  "You generally have 15 days, or 30 if sold electronically, to cancel for a refund less pro-rata charges.": "விகிதாசாரக் கட்டணங்கள் போக திரும்பப் பெற ரத்து செய்ய பொதுவாக 15 நாட்கள், மின்னணு முறையில் விற்கப்பட்டால் 30 நாட்கள் உண்டு.",
  "You initiate each payment. Most control, most effort.": "ஒவ்வொரு கட்டணத்தையும் நீங்களே தொடங்குகிறீர்கள். அதிக கட்டுப்பாடு, அதிக உழைப்பு.",
  "You link a bank account to a UPI app, set a UPI PIN, and authorise each payment with that PIN.": "நீங்கள் வங்கிக் கணக்கை UPI செயலியுடன் இணைத்து, UPI PIN அமைத்து, அந்த PIN மூலம் ஒவ்வொரு பணப்பரிமாற்றத்தையும் அங்கீகரிக்கிறீர்கள்.",
  "You never need to enter a UPI PIN to receive money. Anyone asking you to is attempting fraud.": "பணம் பெற UPI PIN உள்ளிட வேண்டிய அவசியமே இல்லை. அப்படிக் கேட்பவர் மோசடி செய்ய முயல்கிறார்.",
  "You will be repaying long after the trip ends": "பயணம் முடிந்த பின்னும் நீண்ட காலம் திருப்பிச் செலுத்துவீர்கள்",
